SELECT setval(pg_get_serial_sequence('usuarios', 'id'), (SELECT MAX(id) FROM usuarios));

SELECT setval(pg_get_serial_sequence('categorias', 'id'), (SELECT MAX(id) FROM categorias));

SELECT setval(pg_get_serial_sequence('fornecedores', 'id'), (SELECT MAX(id) FROM fornecedores));

SELECT setval(pg_get_serial_sequence('produtos', 'id'), (SELECT MAX(id) FROM produtos));

SELECT setval(pg_get_serial_sequence('produto_imagens', 'id'), (SELECT MAX(id) FROM produto_imagens));

SELECT setval(pg_get_serial_sequence('motivos_movimentacao', 'id'), (SELECT MAX(id) FROM motivos_movimentacao));

SELECT setval(pg_get_serial_sequence('movimentacoes', 'id'), (SELECT MAX(id) FROM movimentacoes));

SELECT setval(pg_get_serial_sequence('vendas', 'id'), (SELECT MAX(id) FROM vendas));

SELECT setval(pg_get_serial_sequence('itens_venda', 'id'), (SELECT MAX(id) FROM itens_venda));

SELECT setval(pg_get_serial_sequence('alertas', 'id'), (SELECT MAX(id) FROM alertas));

UPDATE usuarios SET criado_em = criado_em + (CURRENT_DATE - DATE '2026-09-29') * INTERVAL '1 day';

UPDATE produtos SET criado_em = criado_em + (CURRENT_DATE - DATE '2026-09-29') * INTERVAL '1 day', atualizado_em = atualizado_em + (CURRENT_DATE - DATE '2026-09-29') * INTERVAL '1 day';

UPDATE produto_imagens SET criado_em = criado_em + (CURRENT_DATE - DATE '2026-09-29') * INTERVAL '1 day';

UPDATE movimentacoes SET data_hora = data_hora + (CURRENT_DATE - DATE '2026-09-29') * INTERVAL '1 day';

UPDATE vendas SET data_hora = data_hora + (CURRENT_DATE - DATE '2026-09-29') * INTERVAL '1 day', cancelada_em = cancelada_em + (CURRENT_DATE - DATE '2026-09-29') * INTERVAL '1 day';

UPDATE alertas SET data_criacao = data_criacao + (CURRENT_DATE - DATE '2026-09-29') * INTERVAL '1 day';
